import React, { useState } from 'react';
import MessagesList from '../Pages/Messages/MessagesList';
import ChatWindow from '../Pages/Messages/ChatWindow';
import { Menu, X, MessageSquare } from 'lucide-react';

const MessagesPage = () => {
  const [showChat, setShowChat] = useState(false);
  const [selectedMessage, setSelectedMessage] = useState(null);
  const [isAnimating, setIsAnimating] = useState(false);

  const handleSelectMessage = (message) => {
    setIsAnimating(true);
    setSelectedMessage(message);

    // Animation de transition
    setTimeout(() => {
      setShowChat(true);
      setIsAnimating(false);
    }, 150);
  };

  return (
    <>
      {/* Header */}
      <div className="mb-6 md:mb-8">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl md:text-3xl font-bold text-neutral-900 dark:text-white bg-gradient-to-r from-primary-600 to-secondary-600 bg-clip-text text-transparent">
              Messages
            </h1>
            <p className="text-sm md:text-base text-neutral-600 dark:text-neutral-400 mt-1">
              Gérez vos conversations en temps réel
            </p>
          </div>
          <div className="flex items-center space-x-2">
            <span className="px-3 py-1 text-xs font-medium bg-primary-100 dark:bg-primary-900/30 text-primary-700 dark:text-primary-300 rounded-full">
              3 non lus
            </span>
          </div>
        </div>
      </div>

      <div className="relative">
        {/* Bouton mobile flottant */}
        <button
          onClick={() => setShowChat(!showChat)}
          className="md:hidden fixed bottom-6 right-6 z-40 h-14 w-14 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-2xl shadow-primary-500/30 flex items-center justify-center transition-all duration-300 hover:scale-110 active:scale-95 group"
        >
          <div className="relative">
            {showChat ? (
              <X className="h-6 w-6 transition-transform duration-300" />
            ) : (
              <MessageSquare className="h-6 w-6 transition-transform duration-300 group-hover:scale-110" />
            )}
          </div>
          {!showChat && (
            <span className="absolute -top-1 -right-1 h-5 w-5 bg-red-500 rounded-full border-2 border-white dark:border-neutral-900 animate-pulse"></span>
          )}
        </button>

        {/* Grid principale */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Liste des messages - Left Sidebar */}
          <div className={`lg:col-span-1 ${showChat ? 'hidden md:block' : 'block'}`}>
            <div className={`
              transition-all duration-500 ease-out
              ${isAnimating ? 'scale-95 opacity-50' : 'scale-100 opacity-100'}
            `}>
              <MessagesList onSelectMessage={handleSelectMessage} />
            </div>
          </div>

          {/* Fenêtre de chat - Right Content */}
          <div className={`lg:col-span-2 ${showChat ? 'block' : 'hidden md:block'}`}>
            <div className={`
              transition-all duration-500 ease-out
              ${isAnimating ? 'scale-95 opacity-50' : 'scale-100 opacity-100'}
            `}>
              {selectedMessage ? (
                <ChatWindow 
                  message={selectedMessage} 
                  onClose={() => {
                    setShowChat(false);
                    setTimeout(() => setSelectedMessage(null), 300);
                  }}
                />
              ) : (
                <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-2xl border border-white/40 dark:border-neutral-800/60 p-8 h-[600px] flex flex-col items-center justify-center relative overflow-hidden">
                  {/* Background pattern */}
                  <div className="absolute inset-0 bg-gradient-to-br from-primary-500/5 to-secondary-500/5"></div>
                  <div className="absolute top-0 left-0 w-32 h-32 bg-primary-500/10 rounded-full -translate-x-16 -translate-y-16"></div>
                  <div className="absolute bottom-0 right-0 w-40 h-40 bg-secondary-500/10 rounded-full translate-x-20 translate-y-20"></div>

                  {/* Content */}
                  <div className="relative z-10 text-center max-w-md">
                    <div className="h-20 w-20 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center mx-auto mb-6 shadow-xl animate-float">
                      <MessageSquare className="h-10 w-10 text-white" />
                    </div>
                    <h3 className="text-2xl font-bold text-neutral-900 dark:text-white mb-3">
                      Bienvenue dans les messages
                    </h3>
                    <p className="text-neutral-600 dark:text-neutral-400 mb-6">
                      Sélectionnez une conversation pour commencer à discuter
                    </p>
                    <div className="flex items-center justify-center space-x-4 text-sm text-neutral-500 dark:text-neutral-500">
                      <div className="flex items-center">
                        <div className="h-2 w-2 bg-green-500 rounded-full mr-2"></div>
                        <span>3 en ligne</span>
                      </div>
                      <div className="flex items-center">
                        <div className="h-2 w-2 bg-blue-500 rounded-full mr-2"></div>
                        <span>12 total</span>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default MessagesPage;
